export interface Recipient {
  name: string;
  postalAddress: string;
}

export interface ProviderRequest {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}

export interface ShippingDependencies {
  repository: {
    get(shipmentId: string): Promise<unknown>;
    save(shipmentId: string, record: unknown): Promise<void>;
  };
  atlas: {
    book(request: ProviderRequest): Promise<unknown>;
  };
  beacon?: {
    reserve(request: ProviderRequest): Promise<unknown>;
  };
  logger: {
    info(event: Record<string, unknown>): void;
  };
}

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type FailedAt = Provider | "repository";
type AbortClassification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";

type Rejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

interface ShipmentFields {
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}

interface QueuedShipment extends ShipmentFields {
  state: "queued";
}

interface DispatchedShipment extends ShipmentFields {
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}

interface DeferredShipment extends ShipmentFields {
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: Rejection[];
}

interface UnavailableShipment extends ShipmentFields {
  state: "unavailable";
  rejections: Rejection[];
}

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type PublicError =
  | { code: "invalid_command" | "not_found" | "service_unavailable" }
  | {
      code: "dispatch_aborted";
      shipmentId: string;
      failedAt: FailedAt;
      classification: AbortClassification;
      rejections: Rejection[];
    };

export interface ServiceResponse {
  status: number;
  body: PublicShipment | PublicError;
}

type Command =
  | { op: "get"; shipmentId: string }
  | { op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient };

type CarrierOutcome =
  | Readonly<{ kind: "confirmed"; bookingId: string }>
  | Readonly<{ kind: "refused"; rejection: Rejection }>
  | Readonly<{ kind: "throttled"; retryAtMs: number }>
  | Readonly<{ kind: "failed"; classification: Exclude<AbortClassification, "repository_failure"> }>;

type BaseShipmentRecord = Record<string, unknown> &
  Readonly<{
    schemaVersion: 1;
    id: string;
    routeCode: string;
    parcelGrams: number;
  }>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function isRejection(value: unknown): value is Rejection {
  return isObject(value) && isProvider(value.provider) && isRefusalReason(value.reason);
}

function isRejectionList(value: unknown): value is Rejection[] {
  return Array.isArray(value) && value.every(isRejection);
}

function isBaseShipment(value: Record<string, unknown>): value is BaseShipmentRecord {
  return (
    value.schemaVersion === 1 &&
    typeof value.id === "string" &&
    value.id.length > 0 &&
    typeof value.routeCode === "string" &&
    value.routeCode.length > 0 &&
    typeof value.parcelGrams === "number" &&
    Number.isSafeInteger(value.parcelGrams) &&
    value.parcelGrams > 0
  );
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (!isObject(value) || !isBaseShipment(value)) {
    return undefined;
  }
  if (value.state === "queued") {
    return {
      schemaVersion: 1,
      id: value.id,
      routeCode: value.routeCode,
      parcelGrams: value.parcelGrams,
      state: "queued",
    };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    typeof value.bookingId === "string" &&
    value.bookingId.length > 0 &&
    typeof value.dispatchedAtMs === "number" &&
    Number.isSafeInteger(value.dispatchedAtMs) &&
    value.dispatchedAtMs >= 0
  ) {
    return {
      schemaVersion: 1,
      id: value.id,
      routeCode: value.routeCode,
      parcelGrams: value.parcelGrams,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    typeof value.retryAtMs === "number" &&
    Number.isSafeInteger(value.retryAtMs) &&
    value.retryAtMs >= 0 &&
    isRejectionList(value.rejections)
  ) {
    return {
      schemaVersion: 1,
      id: value.id,
      routeCode: value.routeCode,
      parcelGrams: value.parcelGrams,
      state: "deferred",
      nextProvider: value.nextProvider,
      retryAtMs: value.retryAtMs,
      rejections: value.rejections.map(copyRejection),
    };
  }
  if (value.state === "unavailable" && isRejectionList(value.rejections)) {
    return {
      schemaVersion: 1,
      id: value.id,
      routeCode: value.routeCode,
      parcelGrams: value.parcelGrams,
      state: "unavailable",
      rejections: value.rejections.map(copyRejection),
    };
  }
  return undefined;
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || typeof value.shipmentId !== "string" || value.shipmentId.length === 0) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    typeof value.nowMs !== "number" ||
    !Number.isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function copyRejection(rejection: Rejection): Rejection {
  return { provider: rejection.provider, reason: rejection.reason };
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: shipment.rejections.map(copyRejection),
      };
    case "unavailable":
      return {
        ...fields,
        state: "unavailable",
        rejections: shipment.rejections.map(copyRejection),
      };
  }
}

function abortBody(
  shipmentId: string,
  failedAt: FailedAt,
  classification: AbortClassification,
  rejections: Rejection[],
): PublicError {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections: rejections.map(copyRejection),
  };
}

function logAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: FailedAt,
  classification: AbortClassification,
  rejections: Rejection[],
): void {
  dependencies.logger.info({
    shipmentId,
    action: "aborted",
    failedAt,
    classification,
    rejections: rejections.map(copyRejection),
  });
}

function repositoryAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  rejections: Rejection[],
): ServiceResponse {
  logAbort(dependencies, shipmentId, "repository", "repository_failure", rejections);
  return {
    status: 500,
    body: abortBody(shipmentId, "repository", "repository_failure", rejections),
  };
}

function providerAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: FailedAt,
  classification: Exclude<AbortClassification, "repository_failure">,
  rejections: Rejection[],
): ServiceResponse {
  logAbort(dependencies, shipmentId, failedAt, classification, rejections);
  return {
    status: 500,
    body: abortBody(shipmentId, failedAt, classification, rejections),
  };
}

function carrierRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function classifyAtlasRejection(value: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(value)) {
    return { kind: "failed", classification: "unknown_failure" };
  }
  if (value.code === "cannot_ship") {
    if (!isRefusalReason(value.reason)) {
      return { kind: "failed", classification: "invalid_provider_response" };
    }
    return {
      kind: "refused",
      rejection: { provider: "atlas", reason: value.reason },
    };
  }
  if (value.code === "rate_limited") {
    if (
      typeof value.retryAtMs !== "number" ||
      !Number.isSafeInteger(value.retryAtMs) ||
      value.retryAtMs <= nowMs
    ) {
      return { kind: "failed", classification: "invalid_provider_response" };
    }
    return { kind: "throttled", retryAtMs: value.retryAtMs };
  }
  return { kind: "failed", classification: "unknown_failure" };
}

function classifyBeaconRejection(value: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(value)) {
    return { kind: "failed", classification: "unknown_failure" };
  }
  if (value.type === "rejected") {
    if (!isObject(value.details) || !isRefusalReason(value.details.reason)) {
      return { kind: "failed", classification: "invalid_provider_response" };
    }
    return {
      kind: "refused",
      rejection: { provider: "beacon", reason: value.details.reason },
    };
  }
  if (value.type === "throttled") {
    if (
      !isObject(value.details) ||
      typeof value.details.retryAtMs !== "number" ||
      !Number.isSafeInteger(value.details.retryAtMs) ||
      value.details.retryAtMs <= nowMs
    ) {
      return { kind: "failed", classification: "invalid_provider_response" };
    }
    return { kind: "throttled", retryAtMs: value.details.retryAtMs };
  }
  return { kind: "failed", classification: "unknown_failure" };
}

async function callCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<CarrierOutcome> {
  try {
    const confirmation =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon?.reserve(request);
    if (provider === "atlas") {
      if (
        isObject(confirmation) &&
        typeof confirmation.bookingId === "string" &&
        confirmation.bookingId.length > 0
      ) {
        return { kind: "confirmed", bookingId: confirmation.bookingId };
      }
      return { kind: "failed", classification: "invalid_provider_response" };
    }
    if (
      isObject(confirmation) &&
      typeof confirmation.reference === "string" &&
      confirmation.reference.length > 0
    ) {
      return { kind: "confirmed", bookingId: confirmation.reference };
    }
    return { kind: "failed", classification: "invalid_provider_response" };
  } catch (error) {
    return provider === "atlas"
      ? classifyAtlasRejection(error, nowMs)
      : classifyBeaconRejection(error, nowMs);
  }
}

async function saveCommitted(
  dependencies: ShippingDependencies,
  shipmentId: string,
  record: StoredShipment,
  rejectionsForAbort: Rejection[],
  event: Record<string, unknown>,
  status: number,
): Promise<ServiceResponse> {
  try {
    await dependencies.repository.save(shipmentId, record);
  } catch {
    return repositoryAbort(dependencies, shipmentId, rejectionsForAbort);
  }
  dependencies.logger.info(event);
  return { status, body: publicShipment(record) };
}

function hasProviderRefusal(rejections: Rejection[], provider: Provider): boolean {
  return rejections.some((rejection) => rejection.provider === provider);
}

async function dispatchShipment(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  command: Extract<Command, { op: "dispatch" }>,
): Promise<ServiceResponse> {
  if (shipment.state === "dispatched") {
    return { status: 200, body: publicShipment(shipment) };
  }
  if (shipment.state === "unavailable") {
    return { status: 422, body: publicShipment(shipment) };
  }
  if (shipment.state === "deferred" && command.nowMs < shipment.retryAtMs) {
    return { status: 202, body: publicShipment(shipment) };
  }

  let nextProvider: Provider = shipment.state === "deferred" ? shipment.nextProvider : "atlas";
  const rejections =
    shipment.state === "deferred" ? shipment.rejections.map(copyRejection) : [];

  while (!hasProviderRefusal(rejections, nextProvider)) {
    const outcome = await callCarrier(
      dependencies,
      nextProvider,
      carrierRequest(shipment, command.recipient),
      command.nowMs,
    );

    if (outcome.kind === "confirmed") {
      const dispatched: DispatchedShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "dispatched",
        provider: nextProvider,
        bookingId: outcome.bookingId,
        dispatchedAtMs: command.nowMs,
      };
      return saveCommitted(
        dependencies,
        shipment.id,
        dispatched,
        rejections,
        {
          shipmentId: shipment.id,
          action: "dispatched",
          provider: nextProvider,
        },
        200,
      );
    }

    if (outcome.kind === "throttled") {
      const deferred: DeferredShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "deferred",
        nextProvider,
        retryAtMs: outcome.retryAtMs,
        rejections: rejections.map(copyRejection),
      };
      return saveCommitted(
        dependencies,
        shipment.id,
        deferred,
        rejections,
        {
          shipmentId: shipment.id,
          action: "deferred",
          provider: nextProvider,
          retryAtMs: outcome.retryAtMs,
          rejections: rejections.map(copyRejection),
        },
        202,
      );
    }

    if (outcome.kind === "failed") {
      return providerAbort(dependencies, shipment.id, nextProvider, outcome.classification, rejections);
    }

    rejections.push(copyRejection(outcome.rejection));
    if (nextProvider === "atlas") {
      nextProvider = "beacon";
      continue;
    }

    const unavailable: UnavailableShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "unavailable",
      rejections: rejections.map(copyRejection),
    };
    return saveCommitted(
      dependencies,
      shipment.id,
      unavailable,
      rejections,
      {
        shipmentId: shipment.id,
        action: "unavailable",
        rejections: rejections.map(copyRejection),
      },
      422,
    );
  }

  return providerAbort(dependencies, shipment.id, nextProvider, "invalid_provider_response", rejections);
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      return repositoryAbort(dependencies, command.shipmentId, []);
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(value);
    if (!shipment) {
      return providerAbort(
        dependencies,
        command.shipmentId,
        "repository",
        "invalid_provider_response",
        [],
      );
    }

    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }

    return dispatchShipment(dependencies, shipment, command);
  }

  return { handle };
}
